import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Object} [position]
 * @property {Object} [rotation]
 * @property {Object} [scale]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} videoLoader
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * Creates a sprite‑like textured plane that uses node‑based material.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Atlas region (hard‑coded from spec)
  const REGION = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = REGION.w / REGION.h; // 1.6

  // Geometry sized to region aspect ratio (height = 1 unit)
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Node‑material
  const material = new MeshBasicNodeMaterial();

  // Build UV transform node (no offset/scale because full texture size unknown)
  // If the full atlas is larger, you could adjust using REGION values.
  const uvNode = uv(); // default 0‑1 mapping
  material.map = texture(undefined, uvNode); // placeholder, will be replaced when texture loads

  const mesh = new Mesh(geometry, material);
  mesh.name = config?.name ?? 'CollectionCard3';

  // Store references for cleanup
  const resources = {
    texture: null,
    material,
    geometry,
  };

  // Load texture asynchronously but keep node material synchronous
  if (config?.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      resources.texture = tex;
      // Replace placeholder texture node with the real one
      material.map = texture(tex, uvNode);
      material.needsUpdate = true;
    });
  }

  // No cinematic primitives to apply per spec

  // User data & cleanup
  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    // Dispose texture if loaded
    if (resources.texture) {
      resources.texture.dispose();
      resources.texture = null;
    }
    // Dispose material and geometry
    if (resources.material) {
      resources.material.dispose();
      resources.material = null;
    }
    if (resources.geometry) {
      resources.geometry.dispose();
      resources.geometry = null;
    }
    // Kill any GSAP timelines (none used here but defensive)
    gsap.globalTimeline.clear();
  };

  // Return as a simple Object3D (adapter will position/rotate/scale)
  const container = new Group();
  container.add(mesh);
  return container;
}
